const $=(s)=>document.querySelector(s);
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeLink=(v)=>{try{const u=new URL(v);return u.protocol==='https:'?esc(u.href):'#';}catch{return '#';}};
const number=(v,d=2)=>Number.isFinite(v)?v.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
const money=(v,c='USD')=>Number.isFinite(v)?(c==='USD'?'$':c==='HKD'?'HK$':c==='CNY'?'¥':c+' ')+number(v):'—';
const pct=(v,d=2)=>Number.isFinite(v)?(v>0?'+':'')+number(v,d)+'%':'—';
const date=(s)=>{if(!s)return'Not recorded';const x=new Date(s);return isNaN(x)?esc(s):x.toLocaleString('en-US',{hour12:false});};
