let voiceUtterance=null;
function stopVoice(){if('speechSynthesis' in window){window.speechSynthesis.cancel()}document.querySelectorAll('.avatar.speaking').forEach(x=>x.classList.remove('speaking'));voiceUtterance=null;}
function speakText(text){
  if(!('speechSynthesis' in window)){toast('This browser does not support spoken replies. Try Safari, Chrome or Edge.',true);return;}
  stopVoice();
  const utterance=new SpeechSynthesisUtterance(String(text||'').slice(0,4800));
  const voices=window.speechSynthesis.getVoices().filter(v=>v.lang&&v.lang.toLowerCase().startsWith('en'));
  utterance.voice=voices.find(v=>/samantha|ava|jenny|aria|natural|enhanced|premium/i.test(v.name))||voices[0]||null;
  utterance.lang='en-US';utterance.rate=.93;utterance.pitch=1;
  utterance.onstart=()=>document.querySelectorAll('.avatar').forEach(x=>x.classList.add('speaking'));
  utterance.onend=()=>document.querySelectorAll('.avatar.speaking').forEach(x=>x.classList.remove('speaking'));
  utterance.onerror=()=>document.querySelectorAll('.avatar.speaking').forEach(x=>x.classList.remove('speaking'));
  voiceUtterance=utterance;window.speechSynthesis.speak(utterance);
}

async function api(path,body){const opts={headers:{'X-InvestOne':'1'},credentials:'same-origin'};if(body!==undefined){opts.method='POST';opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(body);}const r=await fetch('/api'+path,opts);let data;try{data=await r.json();}catch{throw Error('Unexpected local service response. Please reopen InvestOne.');}if(!r.ok){const e=Error(data.error||'Request failed');e.status=r.status;throw e;}return data;}
async function streamAIRequest(input, target){
 const response=await fetch('/api/chat/stream',{
  method:'POST',credentials:'same-origin',
  headers:{'X-InvestOne':'1','Content-Type':'application/json','Accept':'text/event-stream'},
  body:JSON.stringify(input)
 });
 if(!response.ok){
  let detail;try{detail=await response.json()}catch{detail={error:'Unable to connect to the ENT207 DeepSeek service'}}
  throw Error(detail.error||'AI request rejected');
 }
 if(!response.body)throw Error('Streaming is not supported by this browser');
 const live=document.querySelector(target);
 let contentBox=null;
 if(live){
  const draft=document.createElement('div');draft.className='bubble assistant streaming';
  const heading=document.createElement('div');heading.className='who';heading.textContent='ENT207 DeepSeek · live response';
  contentBox=document.createElement('div');contentBox.className='body';contentBox.textContent='';
  draft.append(heading,contentBox);live.append(draft);live.scrollTop=live.scrollHeight;
 }
 const reader=response.body.getReader(),decoder=new TextDecoder();
 let pending='',complete=null;
 const handle=(block)=>{
  const lines=block.split(/\r?\n/);
  const kind=lines.find(x=>x.startsWith('event:'))?.slice(6).trim();
  const data=lines.filter(x=>x.startsWith('data:')).map(x=>x.slice(5).trim()).join('\n');
  if(!data)return;
  const payload=JSON.parse(data);
  if(kind==='delta'){if(contentBox){contentBox.textContent+=payload.text||'';live.scrollTop=live.scrollHeight;}}
  else if(kind==='error')throw Error(payload.error||'AI streaming failed');
  else if(kind==='complete')complete=payload;
 };
 try {
  while(true){
   const {value,done}=await reader.read();
   if(done)break;
   pending+=decoder.decode(value,{stream:true});
   let index;
   while((index=pending.indexOf('\n\n'))!==-1){
    const frame=pending.slice(0,index);pending=pending.slice(index+2);
    handle(frame);
   }
  }
  if(pending.trim())handle(pending);
 }finally{reader.releaseLock();}
 if(!complete)throw Error('AI response ended unexpectedly; please check the network');
 return complete;
}

function toast(msg,err=false){const el=$('#toast');el.textContent=msg;el.className='visible'+(err?' err':'');clearTimeout(toast.t);toast.t=setTimeout(()=>el.className='',6500);}
async function loadState(){session=await api('/state');state=session.state;}
function go(p){if(!nav.some(n=>n[0]===p)&&!toolNav.some(n=>n[0]===p))p='chat';if(location.hash==='#'+p){render();}else{location.hash=p;}}
function empty(text,icon='◎'){return `<div class="empty"><div class="emblem">${icon}</div><div>${esc(text)}</div></div>`;}
function notice(text,kind=''){return `<div class="notice ${kind}">${esc(text)}</div>`;}
function metric(label,value,hint='',cls=''){return `<div class="card metric"><div class="label">${esc(label)}</div><div class="value ${cls}">${value}</div><div class="hint">${esc(hint)}</div></div>`;}
function sourceRows(items=[],limit=12){return items.slice(0,limit).map(s=>`<div class="source"><div><span class="source-kind">${esc(s.id?`[${s.id}]`:s.kind==='official'?'Official filing':s.kind==='opinion'?'Public opinion':'Source')}</span>${s.url?`<a href="${safeLink(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`:esc(s.title)}</div><div class="hint">${esc(s.publisher)} · ${esc(s.date||'Date not available')}</div>${s.text?`<div class="snippet">${esc(s.text.slice(0,220))}${s.text.length>220?'…':''}</div>`:''}</div>`).join('')||empty('No sources to display yet');}
function drawChart(series,second=null){if(!series?.length)return `<div class="chart-empty">Historical market data unavailable. No substitute curve is shown.</div>`;const W=760,H=270,L=58,R=15,T=18,B=34;const all=series.map(p=>p.y).concat(second?second.map(p=>p.y):[]).filter(Number.isFinite);if(!all.length)return empty('No valid historical prices');let lo=Math.min(...all),hi=Math.max(...all);const range=hi-lo||Math.abs(hi)*.02||1;lo-=range*.07;hi+=range*.07;const x=(i)=>L+(W-L-R)*i/Math.max(1,series.length-1);const y=(v)=>T+(H-T-B)*(hi-v)/(hi-lo);const path=(a)=>a.map((p,i)=>(i?'L':'M')+x(i).toFixed(2)+','+y(p.y).toFixed(2)).join(' ');let grid='';for(let k=0;k<5;k++){const v=lo+(hi-lo)*k/4,yy=y(v);grid+=`<path d="M${L},${yy} H${W-R}" class="gridline"/><text x="${L-10}" y="${yy+3}" text-anchor="end">${number(v,v<10?2:1)}</text>`;}for(let k=0;k<4;k++){const i=Math.round((series.length-1)*k/3);grid+=`<text x="${x(i)}" y="${H-7}" text-anchor="${k===0?'start':k===3?'end':'middle'}">${esc(series[i].date)}</text>`;}return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Historical price chart"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#a8e2cd" stop-opacity=".16"/><stop offset="1" stop-color="#a8e2cd" stop-opacity="0"/></linearGradient></defs>${grid}<path d="${path(series)} L${x(series.length-1)},${H-B} L${L},${H-B} Z" fill="url(#chart-fill)"/><path d="${path(series)}" class="line-a"/>${second?`<path d="${path(second)}" class="line-b"/>`:''}</svg>`;}
function priceChart(q){return q?drawChart(q.points.map(p=>({date:p.date,y:p.close}))):drawChart([]);}
function quoteCard(s){const q=quotes[s];return `<div class="quote-card" data-action="select-symbol" data-value="${esc(s)}" tabindex="0" role="button"><div class="symbol">${esc(s)}</div><div class="name">${esc(q?.name||'Awaiting market data')}</div><div class="qprice">${q?money(q.price,q.currency):'—'}</div><div class="change ${q?.change>=0?'positive':'negative'}">${q&&q.previous>0?pct(q.change):q?'Previous closing price unavailable':quoteErrors[s]?'Unavailable':'Awaiting data'}</div></div>`;}
async function fetchQuotes(force=false){if(quoteFlight)return quoteFlight;if(!state)return;const symbols=[...new Set([...state.watchlist,...state.holdings.map(h=>h.symbol),'SPY',selected])];quoteFlight=(async()=>{for(let i=0;i<symbols.length;i+=20){const r=await api('/quotes?symbols='+encodeURIComponent(symbols.slice(i,i+20).join(','))+'&range=1y');for(const q of r.quotes){quotes[q.symbol]=q;delete quoteErrors[q.symbol];}for(const [s,e]of Object.entries(r.errors)){quoteErrors[s]=e;delete quotes[s];}}})();try{await quoteFlight;}finally{quoteFlight=null;}}
function portfolioTotals(){let holdings=0,pnl=0,daily=0,complete=true;for(const h of state.holdings){const q=quotes[h.symbol];if(!q||q.currency!=='USD'){complete=false;continue;}holdings+=h.quantity*q.price;pnl+=h.quantity*(q.price-h.cost);if(q.previous>0)daily+=h.quantity*(q.price-q.previous);}return {holdings,pnl,daily,total:holdings+state.cash,complete};}
function holdingsTable(){if(!state.holdings.length)return empty('No positions in your paper account. Try placing a paper trade in My Portfolio.','▤');return `<div class="table-wrap"><table><thead><tr><th>Asset</th><th class="right">Quantity</th><th class="right">Unit cost</th><th class="right">Reference price</th><th class="right">Unrealized P&L</th><th class="right">Reference market value</th></tr></thead><tbody>${state.holdings.map(h=>{const q=quotes[h.symbol];const pnl=q?(q.price-h.cost)*h.quantity:null;return `<tr><td><strong>${esc(h.symbol)}</strong><div class="hint">${esc(q?.name||'Market data unavailable')}</div></td><td class="right">${number(h.quantity,4)}</td><td class="right">${money(h.cost)}</td><td class="right">${q?money(q.price):'—'}</td><td class="right ${pnl>=0?'positive':'negative'}">${money(pnl)}</td><td class="right">${q?money(q.price*h.quantity):'—'}</td></tr>`;}).join('')}</tbody></table></div>`;}
function dashboard(){const t=portfolioTotals(),spy=quotes.SPY;const unread=state.notices.filter(n=>!n.read).length;const err=Object.keys(quoteErrors).length;return `${err?notice(`Quotes unavailable for ${err} symbols. Missing values remain blank; no simulated prices are displayed.`,'info'):''}<div class="grid four">${metric('Paper portfolio equity',t.complete?money(t.total):'Incomplete quotes','Includes paper cash '+money(state.cash)+' · not real assets')}${metric('Estimated daily change',t.complete?money(t.daily):'—','Price movement of current paper positions only',t.daily>=0?'positive':'negative')}${metric('Paper positions',state.holdings.length+' <small> assets</small>','Watchlist: '+state.watchlist.length+' symbols')}${metric('Unread alerts',unread+' <small> alerts</small>','Created '+state.rules.length+' monitoring rules')}</div><div class="grid hero section"><div class="card"><div class="card-header"><div><div class="eyebrow">MARKET BENCHMARK</div><h2>S&P 500 · SPY</h2><div class="hint">Historical${spy?.adjusted?'adjusted':''}closing prices · market trend reference</div></div><div style="text-align:right"><div class="price">${spy?money(spy.price):'—'}</div><div class="${spy?.change>=0?'positive':'negative'}">${spy&&spy.previous>0?pct(spy.change):'Awaiting data'}</div></div></div>${priceChart(spy)}<div class="data-note">${spy?`Source：${esc(spy.source)} · quoted at ${date(spy.as_of)} · retrieved ${date(spy.retrieved)}`:'Market data not yet available. It loads automatically when the provider can be reached.'}</div></div><div class="card"><div class="card-header"><div><h3>AI Research</h3><p class="hint">Market data, news, and personal context in one place.</p></div><span class="pill">✧ DeepSeek</span></div><div style="padding:25px 0"><div style="font-size:35px" class="positive">✧</div><h2>Start with a question</h2><p class="muted">What happened? What does the evidence show? How might it affect my paper portfolio?</p><button class="primary" data-action="chat-prompt" data-value="What has changed recently for NVDA? Separate verified facts from unverified risks and consider my paper portfolio.">Start AI analysis ↗</button></div><hr class="sep"><div class="flex between"><span class="hint">AI connection</span><span class="pill ${session.ai_ready?'':'warn'}">${session.ai_ready?'ENT207 DeepSeek connected':'API key not configured'}</span></div></div></div><div class="section"><div class="section-heading"><h2>Watchlist</h2><a href="#markets">Explore market data →</a></div><div class="quote-strip">${state.watchlist.slice(0,6).map(quoteCard).join('')||empty('No watchlist symbols yet')}</div></div><div class="grid two section"><div class="card"><div class="card-header"><div><h3>My paper positions</h3><div class="hint">Valuations use retrieved quotes only; missing values stay blank.</div></div><a href="#portfolio">Paper trading →</a></div>${holdingsTable()}</div><div class="card"><div class="card-header"><div><h3>Recent alerts</h3><div class="hint">Checked every 10 minutes while the local service runs.</div></div><a href="#automation">Manage monitoring →</a></div>${state.notices.length?state.notices.slice(-3).reverse().map(n=>`<div class="source"><strong>${esc(n.title)}</strong><div class="hint">${date(n.time)}</div><p class="note-body">${esc(n.body.slice(0,180))}</p></div>`).join(''):empty('No triggered alerts yet','◎')}</div></div>`;}
function marketView(){const q=quotes[selected];return `<div class="grid two"><div class="card"><h3>Watchlist and research symbols</h3><form id="watch-form" class="flex"><input name="symbol" placeholder="NVDA / 0700.HK / 600519.SS" aria-label="Ticker symbol" required maxlength="20"><button class="primary" type="submit">Add to watchlist</button></form><div class="hint mt">US tickers, Hong Kong .HK, Shanghai .SS, Shenzhen .SZ; availability depends on the data provider.</div><div class="mt flex wrap">${state.watchlist.map(s=>`<button class="small ${selected===s?'primary':''}" data-action="research" data-value="${esc(s)}">${esc(s)}</button><button class="small ghost danger" title="Remove from watchlist ${esc(s)}" data-action="remove-watch" data-value="${esc(s)}">×</button>`).join('')}</div></div><div class="card"><div class="eyebrow">EVIDENCE BEFORE OPINION</div><h2>Keep prices, disclosures, and opinions separate</h2><p class="hint">Quotes include their own timestamps. News retains headlines, summaries and sources. SEC financial data uses the official interface and requires a contact email entered in Settings.</p><div class="flex"><button data-action="chat-prompt" data-value="Analyze the current research symbol ${esc(selected)}, distinguishing sourced facts, inferences, and missing information.">AI analysis: ${esc(selected)}</button><a href="https://www.sec.gov/edgar/search/#/q=${encodeURIComponent(selected)}" target="_blank" rel="noopener noreferrer">Search official SEC filings ↗</a></div></div></div><div class="card section"><div class="card-header"><div><div class="eyebrow">${esc(selected)}</div><h2>${esc(q?.name||selected)}</h2><span class="hint">${q?.adjusted?'Historical adjusted closing prices':'Historical prices'} · currency ${esc(q?.currency||'Unavailable')}</span></div><div style="text-align:right"><div class="price">${q?money(q.price,q.currency):'—'}</div><div class="${q?.change>=0?'positive':'negative'}">${q&&q.previous>0?pct(q.change):'Price change unavailable'}</div></div></div>${priceChart(q)}<div class="data-note">${q?`${esc(q.source)} · quoted at ${date(q.as_of)} · retrieved ${date(q.retrieved)}`:esc(quoteErrors[selected]||'Loading historical market data…')}</div></div><div id="research-data" class="section"><div class="card"><div class="progress"></div><div class="hint">Loading news and official disclosures…</div></div></div>`;}
function researchDetails(d){const errors=Object.values(d.errors||{});return `${errors.map(x=>notice(x,'info')).join('')}${d.facts?.length?`<div class="card mb"><h2>Officially disclosed financial data</h2><p class="hint">Reporting periods may differ; values are shown as disclosed. Quarterly, cumulative, and annual figures are not automatically mixed.</p><div class="facts">${d.facts.map(f=>`<div class="fact"><div class="hint">${esc(f.label)}</div><div class="value">${money(f.value/1e9)} <small>B</small></div><div class="hint">${esc(f.start||'Period-end balance')} → ${esc(f.end)}<br>${esc(f.form)} · filed ${esc(f.filed)}</div><a class="hint" href="${safeLink(f.url)}" target="_blank" rel="noopener noreferrer">Original disclosure ↗</a></div>`).join('')}</div></div>`:''}<div class="grid two"><div class="card"><h2>News and summaries</h2><p class="hint">RSS headlines and snippets are not substitutes for reading full articles.</p>${sourceRows(d.news)}</div><div class="card"><h2>Official filing</h2><p class="hint">Open the original document or import a supported HTML filing into the research library.</p>${d.filings?.length?d.filings.map(s=>`${sourceRows([s])}<button class="small" data-action="import-filing" data-value="${esc(s.url)}">Import filing text</button>`).join(''):empty('No official filings available yet','▧')}</div></div>`;}
function portfolioView(){const t=portfolioTotals(),realized=state.trades.reduce((s,x)=>s+x.realized,0);return `<div class="notice info">This USD paper-trading account starts with $100,000 virtual cash. No brokerage is connected and no real trades are made. Paper fills use the provider's latest reference price, which may be delayed or from a previous trading day; a simulated 5 bps fee applies to each trade.</div><div class="grid four">${metric('Virtual cash',money(state.cash),'USD')}${metric('Position market value',t.complete?money(t.holdings):'—',t.complete?'All position quotes available':'Some quotes unavailable')}${metric('Unrealized P&L',t.complete?money(t.pnl):'—','Includes simulated fees on purchased assets',t.pnl>=0?'positive':'negative')}${metric('Realized P&L',money(realized),'Sold positions · net of simulated fees',realized>=0?'positive':'negative')}</div><div class="grid two section"><div class="card"><h2>Place a paper trade</h2><form id="trade-form"><div class="grid two"><label>Stock / ETF (USD)<input name="symbol" value="${esc(selected)}" required maxlength="20"></label><label>Side<select name="side"><option value="buy">Paper buy</option><option value="sell">Paper sell</option></select></label></div><label>Shares<input name="quantity" type="number" min="0.000001" max="100000000" step="any" value="1" required></label><div class="hint mb">${quotes[selected]?`${esc(selected)} Latest reference price ${money(quotes[selected].price,quotes[selected].currency)} · ${date(quotes[selected].as_of)}`:'The server fetches a reference price at submission time. No trade is executed if the price is unavailable.'}</div><button type="submit" class="primary">Confirm paper trade</button></form></div><div class="card"><h2>Paper portfolio concentration</h2><p class="hint">Calculated from available USD-denominated reference market values; paper cash is shown separately.</p>${!t.complete?notice('Portfolio weights are unavailable until all required quotes are retrieved.'):t.total>0?[...state.holdings.map(h=>({s:h.symbol,v:quotes[h.symbol].price*h.quantity})),{s:'USD virtual cash',v:state.cash}].map(x=>`<div class="mb"><div class="flex between hint"><span>${esc(x.s)}</span><span>${number(x.v/t.total*100,1)}%</span></div><div class="allocation"><span style="width:${Math.max(0,Math.min(100,x.v/t.total*100))}%"></span></div></div>`).join(''):empty('Awaiting data')}</div></div><div class="card section"><h2>Paper positions</h2>${holdingsTable()}</div><div class="card section"><h2>Paper trade history</h2>${state.trades.length?`<div class="table-wrap"><table><thead><tr><th>Time</th><th>Asset</th><th>Side</th><th class="right">Quantity</th><th class="right">Reference execution price</th><th class="right">Fees</th><th class="right">Realized P&L</th></tr></thead><tbody>${state.trades.slice().reverse().map(t=>`<tr><td>${date(t.time)}<div class="hint">Quote: ${date(t.as_of)}</div></td><td>${esc(t.symbol)}</td><td>${t.side==='buy'?'Buy':'Sell'}</td><td class="right">${number(t.quantity,4)}</td><td class="right">${money(t.price)}</td><td class="right">${money(t.fee)}</td><td class="right">${money(t.realized)}</td></tr>`).join('')}</tbody></table></div>`:empty('No paper trades recorded yet','▤')}</div>`;}
function quantView(){const c=quantResult?.config||{universe:'sectors',range:'2y',top_n:3,fee_bps:10,momentum:50,low_vol:30,trend:20,risk_off:true};return `<div class="card"><div class="eyebrow">QUANTITATIVE RESEARCH LAB</div><h2>Sector Allocation · Explainable Multi-factor Model</h2><p class="hint">Momentum, low volatility and trend signals are cross-sectionally standardized. The portfolio is rebalanced monthly with a next-trading-day execution gap. Buy-and-hold SPY is the benchmark.</p><div class="pill-steps"><span>Real adjusted daily prices</span><span>126-day warm-up</span><span>Signal → next-day close execution</span><span>Costs and cash</span><span>21-day forward Rank IC (out of sample)</span></div><form id="quant-form"><div class="grid four"><label>Universe<select name="universe"><option value="sectors" ${c.universe==='sectors'?'selected':''}>11 US sector ETFs</option><option value="technology" ${c.universe==='technology'?'selected':''}>8 technology stocks</option></select></label><label>Historical range<select name="range"><option value="2y" ${c.range==='2y'?'selected':''}>Last 2 years</option><option value="5y" ${c.range==='5y'?'selected':''}>Last 5 years</option></select></label><label>Hold top N<input name="top_n" type="number" value="${c.top_n}" min="1" max="8" required></label><label>One-way fee (bps)<input name="fee_bps" type="number" value="${c.fee_bps}" min="0" max="100" step="any" required></label></div><div class="grid three"><label>Momentum factor weight<input name="momentum" type="number" value="${c.momentum}" min="0" max="100" required></label><label>Low-volatility factor weight<input name="low_vol" type="number" value="${c.low_vol}" min="0" max="100" required></label><label>Trend factor weight<input name="trend" type="number" value="${c.trend}" min="0" max="100" required></label></div><label class="checkline"><input type="checkbox" name="risk_off" ${c.risk_off?'checked':''}><span>Enable trend filter: select only when both momentum and trend are positive; keep any unused allocation as cash.</span></label><button class="primary" type="submit">Fetch historical prices and run backtest ↗</button></form><div id="quant-status"></div></div><div id="quant-result" class="section">${quantResult?quantResults(quantResult):notice('Backtests use provider-supplied historical prices. If any required asset is missing or its adjustment status cannot be confirmed, the run stops without silently replacing assets or inventing prices.','info')}</div>`;}
function quantResults(r){return `<div class="grid four">${metric('Strategy cumulative return',pct(r.metrics.total_return*100),'SPY over same period '+pct(r.benchmark.total_return*100))}${metric('Annualized return',pct(r.metrics.annual_return*100),r.observations+' trading-day return observations')}${metric('Sharpe',number(r.metrics.sharpe),'Assumed risk-free rate: 0')}${metric('Maximum drawdown',number(r.metrics.max_drawdown*100)+'%','Peak-to-trough decline')}</div><div class="card section"><div class="card-header"><div><h2>Equity curve · after rebalancing costs</h2><div class="hint">${esc(r.start)} → ${esc(r.end)}</div></div><button class="small" data-action="export-quant">Export full results</button></div><div class="legend"><span><i></i>Multi-factor strategy</span><span class="second"><i></i>SPY benchmark</span></div>${drawChart(r.curve.map(p=>({date:p.date,y:p.strategy})),r.curve.map(p=>({date:p.date,y:p.benchmark})))}<div class="data-note">Generated at ${date(r.created)} · fixed universe; no future returns used for contemporaneous selection. Backtests do not establish future profitability.</div></div><div class="grid three section">${metric('Annualized volatility',number(r.metrics.volatility*100)+'%','Based on net daily returns')}${metric('Cumulative turnover',number(r.metrics.turnover,2)+' ×','Total traded notional / period equity')}${metric('Average Rank IC',r.metrics.mean_ic===null?'—':number(r.metrics.mean_ic,3),'Cross-sectional scores vs. next 21-day returns')}</div><div class="card section"><h2>Monthly rebalances and factor effectiveness</h2><div class="table-wrap"><table><thead><tr><th>Signal date</th><th>Execution date</th><th>Selected assets / target weights</th><th class="right">Turnover</th><th class="right">Forward Rank IC</th></tr></thead><tbody>${r.rebalances.slice().reverse().map(x=>`<tr><td>${esc(x.signal_date)}</td><td>${esc(x.execution_date)}</td><td>${x.selections.length?x.selections.map(s=>`${esc(s.symbol)} ${number(s.weight*100,1)}%`).join(' · '):'100% cash'}</td><td class="right">${number(x.turnover,2)}</td><td class="right">${x.ic===null?'—':number(x.ic,3)}</td></tr>`).join('')}</tbody></table></div><details><summary>Data sources and methodological limitations</summary>${r.warnings.map(w=>`<p class="hint mt">${esc(w)}</p>`).join('')}${sourceRows(r.sources,20)}</details></div>`;}
function chatView(){const msgs=state.messages.filter(m=>(m.persona||'assistant')===persona);return `<div class="core-hero"><div class="eyebrow">CORE 01 · YOUR RESEARCH ENTRY POINT</div><h2>AI Investment Chatbot</h2><p>Live ENT207 DeepSeek AI research combines company evidence, your portfolio context, and investment frameworks. Available tools share the same data and research history.</p><div class="core-actions"><a class="core-link" href="#markets">Real market evidence →</a><a class="core-link" href="#documents">Research library →</a><a class="core-link" href="#quant">Multi-factor Quant Lab →</a><a class="core-link" href="#community">Community opinions →</a></div></div><div class="chat-layout"><div class="card chatbox"><div class="chat-context"><span class="pill">${esc(personaNames[persona])}</span><label><span class="screen-reader">Research ticker</span><input id="chat-symbol" value="${esc(selected)}" maxlength="20" aria-label="Research ticker"></label><select id="chat-persona" aria-label="Analysis framework">${Object.entries(personaNames).map(([k,v])=>`<option value="${k}" ${persona===k?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="messages" id="messages">${msgs.length?msgs.map(messageBubble).join(''):`<div class="empty"><div class="emblem">✧</div><h2>Research grounded in evidence</h2><p class="hint">Answers use the selected ticker, paper positions, and personal preferences.<br>Cite retrieved quotes, news, SEC data, and matching local documents.</p></div>`}</div><form class="chat-form" id="chat-form"><textarea name="message" id="chat-input" placeholder="Example: What supports NVDA's growth? Is my paper portfolio overly concentrated?" required maxlength="12000">${esc(chatPrefill)}</textarea><div class="flex between wrap"><label class="checkline"><input name="community" type="checkbox" ${includeCommunity?'checked':''}><span>Include available community opinions (clearly marked unofficial)</span></label><button class="primary" type="submit" ${chatBusy?'disabled':''}>${chatBusy?'Analyzing…':'Send and analyze ↗'}</button></div><div class="hint">Maximum output: ${number(state.profile.max_tokens,0)} tokens per response; ENT207 DeepSeek API charges may apply. Failed requests are not automatically retried. The API key is not stored on disk.</div></form></div><aside class="chat-aside"><div class="card"><h3>Private research context</h3><div class="hint">Risk tolerance</div><p>${esc(labelEnum(state.profile.risk))}</p><div class="hint">Investment horizon</div><p>${esc(labelEnum(state.profile.horizon))}</p><div class="hint">Research interests</div><p>${esc(state.profile.interests)}</p><div class="hint">${state.holdings.length} paper positions · ${state.documents.length} local documents</div><a href="#personal">View personal context →</a></div><div class="card section"><h3>Continue researching</h3><button class="prompt-chip" data-action="prefill" data-value="List the evidence for and against the current investment thesis, then identify the three most important unanswered questions.">What is the supporting and opposing evidence?</button><button class="prompt-chip" data-action="prefill" data-value="Assess sector concentration, single-name risk, and missing information in my paper portfolio.">What risks does my paper portfolio face?</button><a class="hint" href="#documents">Add research documents ↗</a></div></aside></div>`;}
function messageBubble(m){return `<div class="bubble ${m.role==='user'?'user':'assistant'}"><div class="who">${m.role==='user'?'Red Bean & Coix':esc(personaNames[m.persona]||'InvestOne')} · ${date(m.time)}</div><div class="body">${esc(m.content)}</div>${m.sources?.length?`<details><summary>${m.sources.length} contextual sources</summary>${sourceRows(m.sources,40)}</details>`:''}${m.role==='assistant'?`<button type="button" class="listen-voice" data-action="speak-reply">🔊 Listen to analysis</button><button type="button" class="listen-voice" data-action="stop-voice">Stop</button>`:''}</div>`;}
function documentsView(){return `<div class="grid two"><div class="card"><h2>Add research documents</h2><p class="hint">Supports TXT, Markdown, CSV, HTML text, or pasted report content. Text-based PDFs can be imported using local macOS extraction; scanned PDF images are not OCR'd. Relevant excerpts, not entire files, are retrieved for AI questions.</p><form id="doc-form"><label>Import text file<input type="file" id="doc-file" accept=".txt,.md,.csv,.html,.htm,.pdf"></label><label>Document title<input name="name" id="doc-name" required maxlength="200"></label><label>Source URL (optional)<input name="url" type="url" placeholder="https://..."></label><label>Content<textarea name="text" id="doc-text" rows="9" required minlength="10" maxlength="400000" placeholder="Paste a public filing or your own research notes…"></textarea></label><button type="submit" class="primary">Save to local library</button></form></div><div class="card"><h2>Saved documents · ${state.documents.length}</h2><p class="hint">Documents remain on this device. Relevant excerpts may be sent to ENT207 DeepSeek when you ask AI questions.</p>${state.documents.length?state.documents.map(d=>`<div class="source"><div class="flex between"><strong>${esc(d.name)}</strong><button class="small ghost danger" data-action="delete-document" data-value="${esc(d.id)}">Delete</button></div><div class="hint">${number([...d.text].length,0)} characters · ${date(d.created)}</div><p class="snippet">${esc(d.text.slice(0,160))}…</p>${d.url?`<a class="hint" href="${safeLink(d.url)}" target="_blank" rel="noopener noreferrer">View original source ↗</a>`:''}</div>`).join(''):empty('No saved research documents yet','▧')}</div></div>`;}
function automationView(){return `<div class="core-hero"><div class="eyebrow">CORE 03 · ALWAYS-ON RESEARCH WORKFLOW</div><h2>Continuous Monitoring & Automation</h2><p>Create rules for real provider data, earnings, and research reminders. When your Mac service is running, notifications are recorded and optional AI refreshes run only after a trigger.</p></div>${notice('Rules are checked every 10 minutes while the local service runs and the Mac is awake. Closing the browser does not stop the service; monitoring stops during sleep or shutdown, and missed quotes are not replayed.','info')}<div class="grid two"><div class="card"><h2>Create monitoring rule</h2><label>Quick-fill from a sentence (local pattern parser)<div class="flex mt"><input id="rule-natural" placeholder="Notify me when NVDA falls below 100"><button type="button" data-action="parse-rule">Apply</button></div></label><form id="rule-form"><div class="grid two"><label>Ticker symbol<input name="symbol" value="${esc(selected)}" required maxlength="20"></label><label>Rule type<select name="type">${Object.entries(ruleNames).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label></div><div class="grid two"><label>Price / change threshold<input name="threshold" type="number" step="any" value="100"></label><label>News keyword<input name="keyword" placeholder="earnings / guidance"></label></div><label class="checkline"><input type="checkbox" name="auto_ai"><span>Automatically ask AI to re-analyze after a trigger (incurs API charges; off by default and requires an active API key).</span></label><p class="hint">Price alerts fire when first met or met again after resetting. News and filing rules establish a baseline before notifying on new matches. Weekly reviews run after 6 PM Friday in local Mac time.</p><button class="primary" type="submit">Create rule</button></form></div><div class="card"><div class="card-header"><div><h2>Current rules · ${state.rules.length}</h2><p class="hint">Each rule records its latest check, trigger, and source errors.</p></div><button class="small" data-action="check-rules">Check now</button></div>${state.rules.length?state.rules.map(r=>`<div class="rule"><div><div class="rule-title">${esc(r.symbol)} · ${esc(ruleNames[r.type])} ${['price_below','price_above','change_above','change_below'].includes(r.type)?number(r.threshold):esc(r.keyword)}</div><div class="rule-desc">${r.enabled?'Enabled':'Paused'} · ${r.auto_ai?'AI analysis on trigger':'Local notification only'}<br>Last checked ${date(r.last_check)}<br>Last triggered ${date(r.last_triggered)}</div>${r.error?`<div class="hint negative">${esc(r.error)}</div>`:''}</div><div class="flex"><button class="small" data-action="toggle-rule" data-value="${esc(r.id)}">${r.enabled?'Pause':'Enable'}</button><button class="small ghost danger" data-action="delete-rule" data-value="${esc(r.id)}">Delete</button></div></div>`).join(''):empty('No monitoring rules yet','◎')}</div></div><div class="card section"><div class="card-header"><h2>Alert inbox</h2><button class="small" data-action="read-notices">Mark all as read</button></div>${state.notices.length?state.notices.slice().reverse().map(n=>`<div class="source"><h3>${!n.read?'<span class="dot"></span>':''}${esc(n.title)}</h3><div class="hint">${date(n.time)}</div><details><summary>View alerts and analysis</summary><p class="note-body">${esc(n.body)}</p></details></div>`).join(''):empty('Alerts appear when a rule is triggered','◌')}</div>`;}
function communityView(){return `<div class="core-hero"><div class="eyebrow">CORE 04 · OPINION VS EVIDENCE</div><h2>Forum & Community Integration</h2><p>Compare public discussions with corporate disclosures and real market evidence. All community content remains labeled as unverified opinion.</p></div><div class="notice info">Community posts are public opinions, not verified corporate facts. InvestOne attempts to read public Reddit RSS. If access is blocked or unavailable, it shows an error without bypassing authentication or fabricating posts. Other communities are linked to their official websites.</div><div class="flex wrap mb"><form id="community-form" class="flex"><input name="symbol" value="${esc(selected)}" maxlength="20" required aria-label="Community ticker"><button type="submit">Find discussions</button></form><button class="primary" data-action="community-ai">Summarize bull and bear cases with AI</button><a href="https://xueqiu.com/" target="_blank" rel="noopener noreferrer">Xueqiu ↗</a><a href="https://guba.eastmoney.com/" target="_blank" rel="noopener noreferrer">Eastmoney Stock Forum ↗</a></div><div class="grid two"><div class="card"><h2>${esc(selected)} · public discussion</h2><div id="community-data"><div class="progress"></div><p class="hint">Loading public RSS…</p></div></div><div class="card"><h2>Save public opinion</h2><p class="hint">Save publicly accessible posts you have read. Include the ticker in the title and a source link for easier retrieval.</p><form id="opinion-form"><label>Title<input name="title" value="${esc(selected)} · " required maxlength="200"></label><label>Original URL (optional)<input name="url" type="url" placeholder="https://..."></label><label>Post content or your own notes<textarea name="text" required maxlength="12000" rows="7"></textarea></label><button type="submit">Save public opinion</button></form></div></div><div class="card section"><h2>Locally saved opinions · ${state.community.length}</h2>${sourceRows(state.community.slice().reverse(),30)}</div>`;}
function personasView(){
 const cards=[
  {key:'buffett',initial:'WB',name:'Buffett-inspired',title:'Business quality and long-term value',desc:'Assess durable competitive advantages, cash generation, stewardship, and valuation discipline.',url:'https://www.berkshirehathaway.com/letters/letters.html',source:'Berkshire shareholder letters'},
  {key:'munger',initial:'CM',name:'Munger-inspired',title:'Mental models and inversion',desc:'Examine incentives, opportunity costs, cognitive biases, and the strongest case against a thesis.',url:'https://www.berkshirehathaway.com/letters/2014ltr.pdf',source:'Public Munger-related investment writings'},
  {key:'graham',initial:'BG',name:'Graham-inspired',title:'Margin of safety and financial strength',desc:'Consider balance-sheet resilience, conservative assumptions, earning power and downside protection.',url:'https://business.columbia.edu/heilbrunn',source:'Columbia Center for Value Investing'}
 ];
 const active=persona==='assistant'?'buffett':persona;
 const chosen=cards.find(c=>c.key===active)||cards[0];
 const thread=state.messages.filter(m=>(m.persona||'assistant')===active);
 const intro='<div class="core-hero"><div class="eyebrow">CORE 05 · INVESTOR DIGITAL HUMANS</div><h2>Explore investment ideas through three distinct lenses.</h2><p>Select a research framework, ask a question, and continue the conversation without leaving this page. Responses come from the selected DeepSeek model, grounded in financial sources and your portfolio context.</p></div>';
 const note='<div class="notice info">Educational simulations, not the real investors: no endorsement, cloned identity or impersonated voice. The figures are illustrated with original abstract avatars.</div>';
 const options='<div class="grid three persona-selector">'+cards.map(c=>
  '<article class="card persona-card '+(c.key===active?'is-selected':'')+'"><div class="avatar" role="img" aria-label="Original abstract educational avatar, not a person’s likeness">'+c.initial+'<span class="avatar-mouth" aria-hidden="true"></span></div><div class="eyebrow">'+esc(c.name)+'</div><h2>'+esc(c.title)+'</h2><p class="hint">'+esc(c.desc)+'</p><a class="hint mb" href="'+safeLink(c.url)+'" target="_blank" rel="noopener noreferrer">Read original source: '+esc(c.source)+' ↗</a><button type="button" class="'+(c.key===active?'primary':'small')+'" data-action="persona" data-value="'+c.key+'" aria-pressed="'+(c.key===active)+'">'+(c.key===active?'✓ Selected framework':'Select this framework')+'</button></article>'
 ).join('')+'</div>';
 const entries=thread.length?thread.map(messageBubble).join(''):'<div class="persona-empty"><h3>Begin your research discussion</h3><p>Ask about a company, its financial fundamentals or a risk in your own paper portfolio. The reply will follow this investment framework.</p></div>';
 const conversation='<section class="card persona-session" id="persona-session" aria-label="'+esc(chosen.name)+' conversation"><div class="persona-session-head"><div><div class="eyebrow">CURRENT FRAMEWORK</div><h2>'+esc(chosen.name)+' · research dialogue</h2><p class="hint">Use the same source evidence, but ask questions through a different analytical lens.</p></div><span class="pill">Live AI · '+esc(state.profile.model)+'</span></div><div id="persona-messages" class="messages persona-messages" aria-live="polite">'+entries+'</div><form class="persona-chat-form" id="persona-form"><label for="persona-symbol">Research symbol</label><input id="persona-symbol" name="symbol" value="'+esc(selected)+'" maxlength="20" aria-label="Research ticker"><label for="persona-input">Your question</label><textarea id="persona-input" name="message" rows="3" maxlength="12000" required placeholder="What risks would this investment framework consider most important for NVDA?"></textarea><button class="primary" type="submit" '+(chatBusy?'disabled':'')+'>'+(chatBusy?'Analyzing…':'Ask this framework →')+'</button></form><p class="hint persona-disclaimer">The model uses real market/news context where available. Speech playback uses your browser voice. School API quota applies; no response is fabricated when a request fails.</p></section>';
 return intro+note+options+conversation;
}
function personalView(){const t=portfolioTotals();return `<div class="core-hero"><div class="eyebrow">CORE 02 · INVESTOR CONTEXT</div><h2>Personalised Investment Intelligence</h2><p>Your holdings and preferences influence the evidence and risk emphasis in every AI analysis.</p><div class="core-actions"><a class="core-link" href="#portfolio">Manage paper portfolio →</a><a class="core-link" href="#settings">Edit investment profile →</a><a class="core-link" href="#chat">Ask AI using my profile →</a></div></div><div class="grid three">${metric('Paper cash',money(state.cash),'Virtual USD — not real funds')}${metric('Paper holdings',state.holdings.length,'Your currently recorded positions')}${metric('Risk preference',esc(labelEnum(state.profile.risk)),'Saved privately on this Mac')}</div><div class="card section"><div class="card-header"><h2>Current investment context</h2><a href="#portfolio">Paper trading & portfolio →</a></div>${holdingsTable()}<p class="hint mt">If source prices are unavailable, valuations remain unavailable rather than fabricated.</p></div>${settingsView()}`}
function settingsView(){const p=state.profile;return `<div class="grid settings"><div class="card"><h2>Personal research profile</h2><p class="hint">Used to tailor research depth and focus. Not an investor suitability assessment or licensed financial advice.</p><form id="profile-form"><div class="grid two"><label>Risk tolerance<select name="risk">${['Low','Moderate','High'].map(s=>`<option ${p.risk===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Financial knowledge<select name="knowledge">${['Beginner','Some experience','Experienced researcher'].map(s=>`<option ${p.knowledge===s?'selected':''}>${s}</option>`).join('')}</select></label></div><label>Investment horizon<input name="horizon" value="${esc(p.horizon)}" maxlength="100" required></label><label>Research interests and background<textarea name="interests" maxlength="1000">${esc(p.interests)}</textarea></label><label>SEC contact email (optional)<input name="email" type="email" value="${esc(p.email)}" placeholder="Used for the SEC-compliant User-Agent"></label><div class="grid two"><label>ENT207 DeepSeek model name<input name="model" value="DeepSeek-V4-Flash" readonly required maxlength="160" title="Fixed course model" aria-label="Course model: DeepSeek-V4-Flash"></label><label>Maximum output tokens<input name="max_tokens" type="number" min="256" max="1200" value="${p.max_tokens}" required></label></div><p class="hint">The default is 800 tokens to avoid unexpected costs. Model ID is fixed by the course gateway. Use a modest output length to respect the group token quota.</p><button type="submit" class="primary">Save settings</button></form></div><div><div class="card"><h2>API connection</h2><span class="pill ${session.ai_ready?'':'warn'}">${session.ai_ready?'API key held in process memory':'API key not configured'}</span><div class="hint mt">Endpoint</div><p class="note-body">https://apim-ent207tc.azure-api.net/deepseek/openai/v1</p><form id="key-form"><label>Replace ENT207 DeepSeek API key<input name="key" type="password" autocomplete="off" placeholder="Leave blank and save to clear the current key" maxlength="1024"></label><button type="submit">Save for this session</button></form><p class="hint mt">The API key is not written to disk or browser storage. Enter it again after restarting the service or signing out. AI requests send relevant prompts, profile context and evidence excerpts to ENT207 DeepSeek.</p></div><div class="card section"><h2>Local data</h2><p class="hint">Profile, paper trades, chats, and rules remain on this device. Exports exclude the API key.</p><button data-action="export">Export all local data</button><hr class="sep"><div class="hint">InvestOne ${esc(session.version)} · local single-user edition<br>Live-data mode; missing data is never substituted.<br>Monitoring stops when the service is closed or the Mac sleeps.</div><button class="ghost danger mt" data-action="logout">Sign out and clear the API key</button></div><div class="card section"><h2>Live data connectivity · V1.3</h2><p class="hint">Check US and Chinese market history plus news RSS, showing providers and failure reasons. The ENT207 DeepSeek key is only for AI, not financial market feeds. Checks may take up to 40 seconds.</p><button class="primary" data-action="diagnostics">Check live data connections</button><div id="diagnostics-results" class="mt"></div></div></div></div>`;}
function loginView(){generation++;$('#app').innerHTML=`<div class="login"><section class="login-story"><div class="brand"><span class="mark">I</span><div>InvestOne<small>PERSONAL INVESTMENT INTELLIGENCE</small></div></div><div class="intro"><div class="eyebrow">LESS FRAGMENTATION. MORE UNDERSTANDING.</div><h1>Bring fragmented information<br>together into evidence-based<br><span class="positive">investment insights.</span></h1><p>Market data, AI research, paper portfolios, and continuous monitoring.<br>A private investment workspace for Red Bean & Coix.</p><div class="login-graphic"><svg viewBox="0 0 520 160" aria-label="Decorative brand lines, not price data"><path d="M0 135 L35 118 L60 124 L90 88 L130 96 L162 78 L190 88 L215 44 L250 56 L285 30 L320 48 L360 18 L400 34 L440 5 L470 14 L520 0" fill="none" stroke="#a8e2cd" stroke-width="2"/><path d="M0 159 H520 M0 108 H520 M0 57 H520" fill="none" stroke="#304941" stroke-dasharray="2 8"/></svg><div class="hint">Illustration only · not market data</div></div></div><div class="status-line"><span><span class="dot"></span>Your private research workspace</span><span>Web or desktop</span><span>Paper trading only</span></div></section><section class="login-form-wrap"><form id="login-form" class="login-form"><div class="eyebrow">WELCOME TO YOUR WORKSPACE</div><h2>Welcome back.</h2><p class="hint mb">Enter your username and ENT207 DeepSeek API key to start researching.<br>You can use non-AI features without a key.</p><label>Username<input name="username" value="RedBeanCoix" autocomplete="username" required></label><label>ENT207 DeepSeek API Key<input name="key" type="password" autocomplete="off" placeholder="Paste your API key" maxlength="1024"></label><div class="notice info">Course model: DeepSeek-V4-Flash</div><button class="primary" type="submit">Enter InvestOne →</button><p class="login-footer mt">The API key is held in server memory for your session only, not written to disk. AI requests send relevant questions, profile data, paper positions and evidence excerpts to your configured ENT207 Azure gateway.<br><br>Browser-isolated educational workspace. The shared username is not a password. Avoid entering confidential data. No real brokerage is connected.</p></form></section></div>`;}
function render(){if(!state){loginView();return;}const n=nav.find(n=>n[0]===location.hash.slice(1))||toolNav.find(n=>n[0]===location.hash.slice(1));page=n?n[0]:'chat';const token=++generation;const pageTitle=n?n[1]:'AI Investment Chatbot';const descriptions={personal:'Saved profile, paper holdings, and contextual research preferences.',dashboard:'One view of the market, paper assets, alerts, and research signals.',markets:'Build your investment thesis from reference prices and official evidence.',portfolio:'Test ideas with virtual money while learning about prices, fees, and portfolio risk.',quant:'Turn strategy hypotheses into reproducible historical experiments.',chat:'Ask better questions with sourced evidence and your private context.',documents:'Keep reports and notes in a searchable local library.',automation:'Define rules in advance so every alert has a clear trigger.',community:'Understand market debates while separating opinions from facts.',personas:'Test your assumptions through different investment frameworks.',settings:'Your profile, model, data, and privacy settings.'};const views={dashboard,markets:marketView,portfolio:portfolioView,quant:quantView,chat:chatView,personal:personalView,documents:documentsView,automation:automationView,community:communityView,personas:personasView,settings:settingsView};$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><span class="mark">I</span><div>InvestOne<small>INVESTMENT INTELLIGENCE</small></div></div><nav>${nav.map(([key,label,icon,group])=>`${group?`<div class="nav-group">${group}</div>`:''}<a href="#${key}" class="nav-item ${(page===key||toolParents[page]===key)?'active':''}"><span class="nav-icon">${navIcon(key)}</span><span class="nav-label">${esc(label)}</span></a>`).join('')}</nav><div class="sidebar-bottom"><div class="userbox"><span class="dot"></span><strong>Red Bean & Coix</strong><div class="hint">Your private research workspace</div></div><div class="hint" style="font-size:10px">External financial providers may be delayed<br>For education and research only · no brokerage connection</div></div></aside><main class="main"><header class="topbar"><div class="topbar-left">Workspace / <strong>${pageTitle}</strong></div><div class="topbar-actions"><input id="top-search" class="search-small" placeholder="Enter a ticker and press Enter…" aria-label="Search ticker symbols">${session.ai_ready?'<span class="pill">● ENT207 DeepSeek AI configured</span>':'<a href="#settings" class="pill">＋ Connect ENT207 DeepSeek AI Key</a>'}<button class="small ghost" data-action="refresh" title="Refresh data">↻</button><a href="#automation" class="pill">♧ ${state.notices.filter(n=>!n.read).length}</a></div></header><div class="content"><div class="page-heading"><div><div class="eyebrow">INVESTONE · FINANCIAL INTELLIGENCE</div><h1>${pageTitle}</h1><p>${descriptions[page]}</p></div><span class="pill">Live market data · private browser workspace</span></div>${toolParents[page]?`<div class="tool-breadcrumb"><a href="#${toolParents[page]}">← Back to ${esc(nav.find(n=>n[0]===toolParents[page])[1])}</a><span>Professional analysis tool · ${esc(pageTitle)}</span></div>`:''}<div id="page-content">${views[page]()}</div><footer class="footer">InvestOne is for education and research, not personalized trading advice. Quotes may be delayed or unavailable due to provider or network restrictions. All trades are simulated.</footer></div></main>`;
 if(page==='markets'){api('/research?symbol='+encodeURIComponent(selected)).then(d=>{if(generation===token&&$('#research-data'))$('#research-data').innerHTML=researchDetails(d);}).catch(e=>{if(generation===token&&$('#research-data'))$('#research-data').innerHTML=notice(e.message,'error');});}
 if(page==='community'){api('/community?symbol='+encodeURIComponent(selected)).then(d=>{if(generation!==token||!$('#community-data'))return;$('#community-data').innerHTML=(d.error?notice(d.error,'info'):'')+sourceRows(d.items,20);}).catch(e=>{if(generation===token&&$('#community-data'))$('#community-data').innerHTML=notice(e.message,'error');});}
 if(page==='chat'){chatPrefill='';const m=$('#messages');m.scrollTop=m.scrollHeight;}
}
async function refreshPage(withQuotes=false){await loadState();if(withQuotes)await fetchQuotes();render();}
function download(name,value){const b=new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type:'application/json;charset=utf-8'});const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
document.addEventListener('submit',async ev=>{const form=ev.target;if(!(form instanceof HTMLFormElement))return;ev.preventDefault();const fd=new FormData(form);const f=Object.fromEntries(fd.entries());const button=form.querySelector('button[type="submit"]')||form.querySelector('button');if(button?.disabled)return;const old=button?.textContent;if(button){button.disabled=true;button.textContent='Processing…';}try{switch(form.id){
case 'login-form':{const key=f.key||'';form.elements.key.value='';await api('/login',{username:f.username,key});await loadState();render();toast('Signed in to InvestOne · Red Bean & Coix');const token=generation;fetchQuotes().then(()=>{if(generation===token&&['dashboard','markets','portfolio','personal','chat'].includes(page))render();}).catch(e=>toast(e.message,true));break;}
case 'watch-form':selected=f.symbol.trim().toUpperCase();await api('/watchlist',{symbol:selected,remove:false});await refreshPage(true);toast('Added to watchlist');break;
case 'trade-form':await api('/trade',{symbol:f.symbol.trim().toUpperCase(),side:f.side,quantity:Number(f.quantity)});await refreshPage(true);toast('Paper trade recorded; no real money used');break;
case 'profile-form':await api('/profile',{risk:f.risk,horizon:f.horizon,knowledge:f.knowledge,interests:f.interests,email:f.email,model:f.model,max_tokens:Number(f.max_tokens)});await refreshPage();toast('Settings saved to your workspace');break;
case 'key-form':{const key=f.key||'';form.elements.key.value='';await api('/key',{key});await refreshPage();toast(key?'API key held in process memory':'In-memory API key cleared');break;}
case 'doc-form':await api('/documents',{name:f.name,text:f.text,url:f.url||''});await refreshPage();toast('Document saved and searchable in AI chat');break;
case 'opinion-form':await api('/community/save',{title:f.title,text:f.text,url:f.url||''});await refreshPage();toast('Public opinion saved and labeled unverified');break;
case 'community-form':selected=f.symbol.trim().toUpperCase();render();break;
case 'rule-form':await api('/rules',{type:f.type,symbol:f.symbol.trim().toUpperCase(),threshold:Number(f.threshold)||0,keyword:f.keyword||'',auto_ai:fd.has('auto_ai')});await refreshPage();toast('Monitoring rule created; checked every 10 minutes while running');break;
case 'persona-form':{
 if(chatBusy)break;
 chatBusy=true;
 const symbolInput=$('#persona-symbol');
 selected=symbolInput?.value.trim().toUpperCase()||selected;
 const chosen=persona==='assistant'?'buffett':persona;
 const question=f.message.trim();
 if(!question){chatBusy=false;break;}
 const box=$('#persona-messages');
 if(box){box.innerHTML+=messageBubble({role:'user',content:question,time:new Date().toISOString(),persona:chosen})+'<div id="persona-progress" class="progress"></div>';box.scrollTop=box.scrollHeight;}
 try{
  const result=await streamAIRequest({message:question,symbol:selected,persona:chosen,include_community:false},'#persona-messages');
  await loadState();
  if(page==='personas'){render();const updated=$('#persona-messages');if(updated)updated.scrollTop=updated.scrollHeight;}
  if(result.warnings?.length)toast(result.warnings.join('; '));else toast('Framework analysis completed and saved');
 }finally{
  chatBusy=false;
  $('#persona-progress')?.remove();
  const submit=$('#persona-form button[type="submit"]');
  if(submit){submit.disabled=false;submit.textContent='Ask this framework →';}
 }
 break;
}
case 'chat-form':{if(chatBusy)break;chatBusy=true;selected=$('#chat-symbol').value.trim().toUpperCase();persona=$('#chat-persona').value;const question=f.message;const box=$('#messages');box.innerHTML+=messageBubble({role:'user',content:question,time:new Date().toISOString(),persona})+'<div id="chat-progress"><div class="progress"></div><p class="hint">Retrieving evidence and contacting ENT207 DeepSeek; requests are not automatically retried.</p></div>';box.scrollTop=box.scrollHeight;$('#chat-input').value='';try{const result=await streamAIRequest({message:question,symbol:selected,persona,include_community:fd.has('community')},'#messages');await loadState();if(page==='chat')render();if(result.warnings.length)toast(result.warnings.join('；'));else toast('Analysis completed and saved to local chat history');}finally{chatBusy=false;$('#chat-progress')?.remove();if(page==='chat'){const b=$('#chat-form button[type="submit"]');if(b){b.disabled=false;b.textContent='Send and analyze ↗';}}}break;}
case 'quant-form':{const config={universe:f.universe,range:f.range,top_n:Number(f.top_n),fee_bps:Number(f.fee_bps),momentum:Number(f.momentum),low_vol:Number(f.low_vol),trend:Number(f.trend),risk_off:fd.has('risk_off')};$('#quant-status').innerHTML='<div class="progress"></div><div class="hint">Fetching real historical data for the complete universe and running the backtest…</div>';try{quantResult=await api('/quant',config);if(page==='quant'&&$('#quant-result'))$('#quant-result').innerHTML=quantResults(quantResult);toast('Backtest completed; results and sources are available for export');}finally{if($('#quant-status'))$('#quant-status').innerHTML='';}break;}
}}catch(e){toast(e.message,true);if(e.status===401&&form.id!=='login-form'){state=null;session=null;loginView();}if(form.id==='quant-form'&&$('#quant-result'))$('#quant-result').innerHTML=notice(e.message,'error');}finally{if(button?.isConnected){button.disabled=false;button.textContent=old;}}});
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el||el.disabled)return;const act=el.dataset.action,value=el.dataset.value;const old=el.textContent;let lock=false;try{switch(act){
case 'select-symbol':selected=value;go('markets');break;
case 'research':selected=value;render();break;
case 'refresh':lock=true;el.disabled=true;await refreshPage(true);toast('Refreshed; original data timestamps preserved');break;
case 'remove-watch':lock=true;el.disabled=true;await api('/watchlist',{symbol:value,remove:true});await refreshPage();break;
case 'chat-prompt':chatPrefill=value;persona='assistant';includeCommunity=false;go('chat');break;
case 'prefill':$('#chat-input').value=value;$('#chat-input').focus();break;
case 'speak-reply':{const bubble=el.closest('.bubble');speakText(bubble?.querySelector('.body')?.textContent||'');break;}
case 'stop-voice':stopVoice();break;
case 'persona':persona=value;includeCommunity=false;render();document.getElementById('persona-session')?.scrollIntoView({behavior:'smooth',block:'nearest'});break;
case 'community-ai':persona='assistant';includeCommunity=true;chatPrefill='Using the retrieved '+selected+' community discussions and locally saved public opinions, summarize bullish and bearish evidence, main disagreements, and unverified claims. If no posts are available, say so; never fabricate them.';go('chat');break;
case 'parse-rule':{const text=$('#rule-natural').value.trim(),form=$('#rule-form');const s=text.match(/\b[A-Za-z][A-Za-z0-9.\-]{0,19}\b/);if(s)form.elements.symbol.value=s[0].toUpperCase();const num=text.match(/(-?\d+(?:\.\d+)?)/);if(/friday/i.test(text)){form.elements.type.value='weekly';}else if(/below|under|falls? below|<=/i.test(text)&&num){form.elements.type.value=text.includes('%')?'change_below':'price_below';form.elements.threshold.value=num[1];}else if(/above|over|exceeds?|>=/i.test(text)&&num){form.elements.type.value=text.includes('%')?'change_above':'price_above';form.elements.threshold.value=num[1];}else{throw Error('Examples: Notify me if NVDA falls below 100; alert me when SPY exceeds 700; review my portfolio every Friday. Use the form below for complex rules.');}toast('Rule form filled; review it and select Create rule.');break;}
case 'check-rules':lock=true;el.disabled=true;el.textContent='Checking…';{const result=await api('/rules/check',{});await refreshPage();toast('Check completed; '+result.triggered+' new alerts');}break;
case 'toggle-rule':{lock=true;el.disabled=true;const r=state.rules.find(x=>x.id===value);await api('/rules/update',{id:value,enabled:!r.enabled,delete:false});await refreshPage();break;}
case 'delete-rule':if(!confirm('Delete this monitoring rule?'))return;lock=true;el.disabled=true;await api('/rules/update',{id:value,enabled:false,delete:true});await refreshPage();break;
case 'read-notices':lock=true;el.disabled=true;await api('/notices/read',{});await refreshPage();toast('Alerts marked as read');break;
case 'delete-document':if(!confirm('Delete this document from the local library?'))return;lock=true;el.disabled=true;await api('/documents/delete',{id:value});await refreshPage();break;
case 'import-filing':lock=true;el.disabled=true;el.textContent='Importing…';await api('/filing/import',{symbol:selected,url:value});await loadState();toast('SEC filing text saved to the research library');break;
case 'export':download('InvestOne-local-data.json',await api('/export'));toast('Local data exported without the API key');break;
case 'export-quant':if(quantResult)download('InvestOne-backtest-results.json',quantResult);break;
case 'diagnostics':{lock=true;el.disabled=true;el.textContent='Testing live connectivity…';const d=await api('/diagnostics');const root=$('#diagnostics-results');if(root){const items=Object.entries(d.checks||{}).map(([name,c])=>`<div class="source"><strong>${esc(name)} · ${c.status==='ok'?'Live data retrieved':'Request failed'}</strong><div class="hint">${esc(c.source||c.error||'No result')} · ${number(c.duration_ms,0)}ms ${c.as_of?'· data '+date(c.as_of):''}</div></div>`).join('');root.innerHTML=`<p class="hint">App version ${esc(d.version)} · network mode ${esc(d.mode)} · checked at ${date(d.timestamp)}.${d.key_configured?'AI key supplied (no paid AI request made)':'AI key not configured'}</p>${items}`;}}break;
case 'logout':await api('/logout',{});state=null;session=null;quotes={};quoteErrors={};loginView();break;
}}catch(e){toast(e.message,true);}finally{if(lock&&el.isConnected){el.disabled=false;el.textContent=old;}}});
document.addEventListener('change',async ev=>{if(ev.target.id==='chat-persona'){persona=ev.target.value;render();}if(ev.target.id==='doc-file'){const f=ev.target.files?.[0];if(!f)return;try{if(f.size>8*1024*1024)throw Error('File limit: 8 MB. Split longer reports into smaller excerpts.');let text;if(/\.pdf$/i.test(f.name)){toast('Extracting text from your PDF…');const b64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(f);});const d=await api('/pdf-text',{data:b64});text=d.text;}else{if(f.size>1200000)throw Error('Text file limit is approximately 1.2 MB; split it before importing.');text=await f.text();if(/\.html?$/i.test(f.name)){const d=new DOMParser().parseFromString(text,'text/html');d.querySelectorAll('script,style').forEach(n=>n.remove());text=d.body.textContent;}}if($('#doc-text')){$('#doc-text').value=text;$('#doc-name').value=f.name;toast('Text loaded; review and save it.');}}catch(e){toast(e.message||'Failed to read the document',true);}}});
document.addEventListener('keydown',async ev=>{if(ev.target.id==='top-search'&&ev.key==='Enter'){ev.preventDefault();const s=ev.target.value.trim().toUpperCase();if(!/^[A-Z0-9^][A-Z0-9.^=\-]{0,19}$/.test(s)){toast('Enter a valid ticker, such as NVDA or 0700.HK',true);return;}selected=s;go('markets');try{await fetchQuotes();if(page==='markets')render();}catch(e){toast(e.message,true);}}if(ev.target.id==='chat-input'&&ev.key==='Enter'&&(ev.metaKey||ev.ctrlKey)){ev.preventDefault();if(!chatBusy)$('#chat-form').requestSubmit();}if(ev.target.matches('.quote-card')&&(ev.key==='Enter'||ev.key===' ')){ev.preventDefault();ev.target.click();}});
window.addEventListener('hashchange',()=>{if(state)render();});
(async()=>{if(location.protocol==='file:'){location.href='http://127.0.0.1:18791/';return;}try{await loadState();render();const token=generation;await fetchQuotes();if(generation===token&&['dashboard','markets','portfolio','personal','chat'].includes(page))render();}catch(e){if(e.status===401){state=null;loginView();}else if(!state){$('#app').innerHTML='<div class="boot"><span class="mark">I</span><h2>InvestOne service unavailable</h2><p>'+esc(e.message)+'</p><p class="hint">Reload this page or check server status.</p></div>';}else toast(e.message,true);}})();
